examples.code:
.izgara {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
}

/* fr = fractional unit (oransal birim) */

.sayfa {
    display: grid;
    grid-template-areas:
        'header header'
        'sidebar main'
        'footer footer';
    grid-template-columns: 250px 1fr;
    grid-template-rows: auto 1fr auto;
    min-height: 100vh;
}

header { grid-area: header; }
.sidebar { grid-area: sidebar; }
main { grid-area: main; }
footer { grid-area: footer; }
